// The Project browser's Scripts root and Create → Behaviour (roadmap
// Phase 2 item 1): `lib/` listed beside the assets, a script opened in the
// IDE, a behaviour written from the template, generated by `fynkel
// codegen` (`CodegenCheck.generate`, project-only) and registered with the
// session.
import 'dart:async';
import 'dart:convert';
import 'dart:io';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:fynkel_editor/src/inspector/codegen_check.dart';
import 'package:fynkel_editor/src/project_browser/project_browser_model.dart';
import 'package:fynkel_editor/src/project_browser/project_panel.dart';
import 'package:fynkel_editor/src/project_browser/scripts.dart';

import 'support/fakes.dart';

/// A game package on disk: `pubspec.yaml`, `lib/main.dart`,
/// `lib/game/{player,hud}.dart`, `lib/generated/behaviours.g.dart`.
Directory scriptsProject() {
  final dir = Directory.systemTemp.createTempSync('fynkel_editor_scripts');
  File('${dir.path}/pubspec.yaml').writeAsStringSync('name: demo\n');
  for (final f in ['main.dart', 'game/player.dart', 'game/hud.dart', 'generated/behaviours.g.dart']) {
    File('${dir.path}/lib/$f')
      ..createSync(recursive: true)
      ..writeAsStringSync('// $f\n');
  }
  Directory('${dir.path}/lib/.hidden').createSync();
  File('${dir.path}/lib/game/notes.txt').writeAsStringSync('not dart');
  return dir;
}

Map<String, Object?> metadataOf(List<(String, String)> behaviours) => {
  'package': 'demo',
  'behaviours': [
    for (final (id, file) in behaviours) {'id': id, 'library': 'package:demo/$file'},
  ],
};

void main() {
  group('scripts.dart', () {
    test('names, namespaces and the behaviours per file', () {
      expect(snakeCase('HoverPad'), 'hover_pad');
      expect(snakeCase('HUDLabel'), 'hud_label');
      expect(snakeCase('Door2Opener'), 'door2_opener');
      expect(isBehaviourClassName('HoverPad'), isTrue);
      expect(isBehaviourClassName('hoverPad'), isFalse);
      expect(isBehaviourClassName('Hover Pad'), isFalse);
      expect(isBehaviourClassName('Hover_Pad'), isFalse);
      expect(behaviourNamespace(null), 'game');
      expect(behaviourNamespace(metadataOf([('arena.Player', 'x.dart'), ('arena.Gate', 'y.dart')])), 'arena');
      expect(behaviourNamespace(metadataOf([('a.Player', 'x.dart'), ('b.Gate', 'y.dart')])), 'game');
      expect(behaviourScripts(metadataOf([('game.Player', 'game/player.dart'), ('game.Ghost', 'game/player.dart')])), {
        'game/player.dart': ['game.Player', 'game.Ghost'],
      });
      expect(isGeneratedScript('generated/behaviours.g.dart'), isTrue);
      expect(isGeneratedScript('game/x.g.dart'), isTrue);
      expect(isGeneratedScript('game/player.dart'), isFalse);
    });

    test('ScriptTree lists folders and .dart files, hidden entries skipped', () {
      final dir = scriptsProject();
      addTearDown(() => dir.deleteSync(recursive: true));
      final tree = ScriptTree.read('${dir.path}/lib');
      expect(tree.folders, ['game', 'generated']);
      expect(tree.files, ['game/hud.dart', 'game/player.dart', 'generated/behaviours.g.dart', 'main.dart']);
      expect(ScriptTree.read('${dir.path}/nothing').files, isEmpty);
    });

    test('writeBehaviour: the template, refused for a bad name, a file or an id already there', () {
      final dir = scriptsProject();
      addTearDown(() => dir.deleteSync(recursive: true));
      final lib = '${dir.path}/lib';
      final b = writeBehaviour(libDir: lib, folder: 'game/pads', className: 'HoverPad', namespace: 'game');
      expect(b.id, 'game.HoverPad');
      expect(b.rel, 'game/pads/hover_pad.dart');
      final text = File(b.file).readAsStringSync();
      expect(text, contains("@FynkelBehaviour(id: 'game.HoverPad')"));
      expect(text, contains('class HoverPad extends Behaviour'));
      expect(text, contains('void update(UpdateContext context)'));
      expect(
        () => writeBehaviour(libDir: lib, folder: 'game/pads', className: 'HoverPad', namespace: 'game'),
        throwsA(isA<FormatException>().having((e) => e.message, 'message', contains('already there'))),
      );
      expect(
        () => writeBehaviour(libDir: lib, folder: '', className: 'hover', namespace: 'game'),
        throwsA(isA<FormatException>().having((e) => e.message, 'message', contains('not a class name'))),
      );
      expect(
        () => writeBehaviour(libDir: lib, folder: '', className: 'Player', namespace: 'game', taken: {'game.Player'}),
        throwsA(isA<FormatException>()),
      );
      expect(File('$lib/player.dart').existsSync(), isFalse);
    });
  });

  group('CodegenCheck.generate', () {
    test('runs the project-only codegen and reads its report', () async {
      final dir = scriptsProject();
      addTearDown(() => dir.deleteSync(recursive: true));
      final runner = RecordingRunner(
        stdout: jsonEncode({
          'ok': true,
          'check': false,
          'native': {'status': 'skipped'},
          'project': {'dir': dir.path, 'status': 'written', 'files': 3, 'types': 3},
        }),
      );
      final check = CodegenCheck(
        projectDir: dir.path,
        run: runner.call,
        cli: () => '/fake/fynkel',
        repoRoot: () => '/r',
      );
      addTearDown(check.dispose);
      expect(await check.generate(), isNull);
      expect(check.status, CodegenStatus.upToDate);
      // Never --root: the engine's own generated files are not the editor's to write.
      expect(runner.calls.single.$2, ['codegen', '--project', dir.path, '--project-only', '--json']);
      expect(check.arguments(), ['codegen', '--check', '--project', dir.path, '--root', '/r', '--json']);

      runner
        ..exitCode = 1
        ..stdout = jsonEncode({
          'ok': false,
          'project': {'status': 'error', 'error': 'build_runner failed'},
        });
      expect(await check.generate(), 'build_runner failed');
      expect(check.status, CodegenStatus.failed);

      final noCli = CodegenCheck(projectDir: dir.path, run: runner.call, cli: () => null, repoRoot: () => null);
      addTearDown(noCli.dispose);
      expect(await noCli.generate(), contains('no `fynkel` CLI'));
    });
  });

  test('a saved script regenerates and reloads; generated files and other files do not', () async {
    final dir = scriptsProject();
    addTearDown(() => dir.deleteSync(recursive: true));
    final runner = RecordingRunner(
      stdout: jsonEncode({
        'ok': true,
        'check': false,
        'native': {'status': 'skipped'},
        'project': {'dir': dir.path, 'status': 'written', 'files': 2, 'types': 1},
      }),
    );
    final check = CodegenCheck(projectDir: dir.path, run: runner.call, cli: () => '/fake/fynkel', repoRoot: () => null);
    addTearDown(check.dispose);
    final changes = StreamController<List<String>>();
    addTearDown(changes.close);
    var reloads = 0;
    check.recompileOnSave(changes.stream, reload: () => reloads++, delay: const Duration(milliseconds: 20));

    changes.add([
      '${dir.path}/lib/generated/behaviours.g.dart',
      '${dir.path}/assets/a.png',
      '${dir.path}/lib/x.g.dart',
    ]);
    await Future<void>.delayed(const Duration(milliseconds: 80));
    expect(runner.calls, isEmpty);

    // Two quick saves: one run, then the reload.
    changes.add(['${dir.path}/lib/game/player.dart']);
    changes.add(['${dir.path}/lib/game/player.dart']);
    await Future<void>.delayed(const Duration(milliseconds: 80));
    expect(runner.calls.single.$2, contains('--project-only'));
    expect(reloads, 1);
    expect(check.generating, isFalse);

    // A failed run does not reload.
    runner.exitCode = 1;
    runner.stdout = jsonEncode({
      'ok': false,
      'native': {'status': 'skipped'},
      'project': {'status': 'error', 'error': 'build_runner failed'},
    });
    changes.add(['${dir.path}/lib/game/player.dart']);
    await Future<void>.delayed(const Duration(milliseconds: 80));
    expect(runner.calls, hasLength(2));
    expect(reloads, 1);
    expect(check.status, CodegenStatus.failed);
  });

  test('a changed asset regenerates assets.g.dart (--assets-only); a script or lib file does not', () async {
    final dir = scriptsProject();
    addTearDown(() => dir.deleteSync(recursive: true));
    final runner = RecordingRunner(
      stdout: jsonEncode({
        'ok': true,
        'check': false,
        'assets': {'status': 'written'},
      }),
    );
    final check = CodegenCheck(projectDir: dir.path, run: runner.call, cli: () => '/fake/fynkel', repoRoot: () => null);
    addTearDown(check.dispose);
    final changes = StreamController<List<String>>();
    addTearDown(changes.close);
    check.regenerateAssetsOn(changes.stream, assetsDir: '${dir.path}/assets', delay: const Duration(milliseconds: 20));

    changes.add(['${dir.path}/lib/game/player.dart', '${dir.path}/lib/generated/assets.g.dart']);
    await Future<void>.delayed(const Duration(milliseconds: 80));
    expect(runner.calls, isEmpty, reason: 'its own output does not loop');

    // An import and its sidecar: one run.
    changes.add(['${dir.path}/assets/models/crate.glb']);
    changes.add(['${dir.path}/assets/models/crate.glb.meta.json']);
    await Future<void>.delayed(const Duration(milliseconds: 80));
    expect(runner.calls.single.$2, ['codegen', '--project', dir.path, '--assets-only', '--json']);

    runner
      ..exitCode = 1
      ..stdout = jsonEncode({
        'ok': false,
        'assets': {'status': 'error', 'error': 'fynkel.project.json: bad'},
      });
    expect(await check.regenerateAssets(), 'fynkel.project.json: bad');
    runner.stdout = '';
    runner.stderr = 'error: unknown argument --assets-only';
    expect(await check.regenerateAssets(), contains('unknown argument'));
  });

  test(
    'the watch: every build reports, a written one reloads, Create waits for it, an ended watch falls back',
    () async {
      final dir = scriptsProject();
      addTearDown(() => dir.deleteSync(recursive: true));
      final runner = RecordingRunner(
        stdout: jsonEncode({
          'ok': true,
          'native': {'status': 'skipped'},
          'project': {'status': 'written', 'files': 2, 'types': 1},
        }),
      );
      final process = FakePlayProcess();
      final started = <List<String>>[];
      final check = CodegenCheck(
        projectDir: dir.path,
        run: runner.call,
        cli: () => '/fake/fynkel',
        repoRoot: () => null,
        start: (exe, args, {workingDirectory, environment}) async {
          started.add([exe, ...args]);
          return process;
        },
      );
      addTearDown(check.dispose);
      final changes = StreamController<List<String>>();
      addTearDown(changes.close);
      var reloads = 0;
      await check.watch(changes.stream, reload: () => reloads++);
      expect(check.watching, isTrue);
      expect(started.single, ['/fake/fynkel', 'codegen', '--watch', '--project', dir.path]);

      process.emit('{"event":"building"}');
      await FakePlayProcess.settle();
      expect(check.status, CodegenStatus.running);
      expect(check.generating, isTrue);
      process.emit('{"event":"built","status":"upToDate","types":1}');
      await FakePlayProcess.settle();
      expect(check.status, CodegenStatus.upToDate);
      expect(reloads, 0, reason: 'nothing was written');

      // A save: the watch sees it, not a run per save.
      changes.add(['${dir.path}/lib/game/player.dart']);
      process.emit('{"event":"building"}');
      process.emit('{"event":"built","status":"written","types":1}');
      await Future<void>.delayed(const Duration(milliseconds: 600));
      expect(reloads, 1);
      expect(runner.calls, isEmpty);

      // Create → Behaviour waits for the build its new file starts.
      var created = 'pending';
      unawaited(check.generate().then((p) => created = p ?? 'built'));
      await FakePlayProcess.settle();
      process.emit('{"event":"building"}');
      await FakePlayProcess.settle();
      expect(created, 'pending');
      process.emit(
        '{"event":"failed","error":"E fynkel_generator:behaviours on lib/\$lib\$:\\n12:3: Expected an identifier."}',
      );
      await FakePlayProcess.settle();
      expect(created, contains('Expected an identifier'));
      expect(check.status, CodegenStatus.failed);
      expect(runner.calls, isEmpty);

      // `check` has nothing to add while watching.
      await check.check();
      expect(runner.calls, isEmpty);

      // The watch ends (a CLI without --watch ends at once): one run per save again.
      process.exitWith(1);
      await FakePlayProcess.settle();
      expect(check.watching, isFalse);
      changes.add(['${dir.path}/lib/game/player.dart']);
      await Future<void>.delayed(const Duration(milliseconds: 700));
      expect(runner.calls.single.$2, contains('--project-only'));
      expect(reloads, 2);
    },
  );

  test('a watch that cannot start falls back to one run per save', () async {
    final dir = scriptsProject();
    addTearDown(() => dir.deleteSync(recursive: true));
    final runner = RecordingRunner(
      stdout: jsonEncode({
        'ok': true,
        'native': {'status': 'skipped'},
        'project': {'status': 'upToDate', 'types': 1},
      }),
    );
    final check = CodegenCheck(
      projectDir: dir.path,
      run: runner.call,
      cli: () => '/fake/fynkel',
      repoRoot: () => null,
      start: (exe, args, {workingDirectory, environment}) async => throw const ProcessException('fynkel', []),
    );
    addTearDown(check.dispose);
    final changes = StreamController<List<String>>();
    addTearDown(changes.close);
    await check.watch(changes.stream, reload: () {});
    expect(check.watching, isFalse);
    changes.add(['${dir.path}/lib/game/player.dart']);
    await Future<void>.delayed(const Duration(milliseconds: 700));
    expect(runner.calls, hasLength(1));
  });

  group('ProjectBrowserModel scripts', () {
    test('the Scripts root: folders, files, kinds, search, the list view, file changes, recall', () async {
      final dir = scriptsProject();
      addTearDown(() => dir.deleteSync(recursive: true));
      final project = FakeProject(dir: dir.path)..metadata = metadataOf([('game.Player', 'game/player.dart')]);
      final model = ProjectBrowserModel(project: project);
      addTearDown(model.dispose);
      expect(model.hasScripts, isTrue);
      expect(model.inScripts, isFalse);
      expect(model.newBehaviourFolder, 'game');

      model.showScripts();
      expect(model.inScripts, isTrue);
      expect(model.visibleScriptFolders, ['game', 'generated']);
      expect(model.visibleScripts, ['main.dart']);
      model.showScripts('game');
      expect(model.visibleScripts, ['game/hud.dart', 'game/player.dart']);
      expect(model.scriptKind('game/player.dart'), 'behaviour');
      expect(model.scriptKind('game/hud.dart'), 'script');
      expect(model.scriptKind('generated/behaviours.g.dart'), 'generated');
      expect(model.newBehaviourFolder, 'game');
      model.showScripts('nowhere');
      expect(model.scriptFolder, 'game');

      // Keys step the one selected script.
      model.stepScript(1);
      expect(model.scriptLead, 'game/hud.dart');
      model.stepScript(1);
      model.stepScript(1);
      expect(model.scriptLead, 'game/player.dart');

      // A search looks under the shown folder, by path and by behaviour id.
      model.scriptsUp();
      model.setQuery('game.play');
      expect(model.visibleScriptFolders, isEmpty);
      expect(model.visibleScripts, ['game/player.dart']);
      model.setQuery('');
      model.setView(BrowserView.list);
      expect(model.visibleScripts, hasLength(4));
      model.setView(BrowserView.folders);

      // A file the watcher saw under lib/ re-reads the tree.
      File('${dir.path}/lib/extra.dart').writeAsStringSync('');
      project.filesChanged(['${dir.path}/lib/extra.dart']);
      await Future<void>.delayed(Duration.zero);
      expect(model.visibleScripts, ['extra.dart', 'main.dart']);

      // Where the browser was comes back, and an asset folder leaves Scripts.
      model.showScripts('game');
      final saved = model.remembered;
      expect(saved['scripts'], 'game');
      model.setFolder('');
      expect(model.inScripts, isFalse);
      model.recall(saved);
      expect((model.inScripts, model.scriptFolder), (true, 'game'));
    });

    test('New Behaviour: written, generated, registered; each failure said', () async {
      final dir = scriptsProject();
      addTearDown(() => dir.deleteSync(recursive: true));
      final project = FakeProject(dir: dir.path)..metadata = metadataOf([('arena.Player', 'game/player.dart')]);
      final model = ProjectBrowserModel(project: project);
      addTearDown(model.dispose);
      expect(model.canNewBehaviour, isTrue);

      final b = model.writeNewBehaviour('HoverPad')!;
      expect(b.id, 'arena.HoverPad');
      expect(b.rel, 'game/hover_pad.dart');
      expect((model.inScripts, model.scriptFolder, model.scriptLead), (true, 'game', 'game/hover_pad.dart'));

      // codegen lists the new type: the session registers it.
      final busy = <String?>[];
      model.addListener(() => busy.add(model.scriptsBusy));
      final problem = await model.generateBehaviour(b, () async {
        project.metadata = metadataOf([('arena.Player', 'game/player.dart'), ('arena.HoverPad', b.rel)]);
        return null;
      });
      expect(problem, isNull);
      expect(busy.first, contains('Generating arena.HoverPad'));
      expect(model.scriptsBusy, isNull);
      final (kind, args) = project.operations.last;
      expect(kind, 'registerBehaviour');
      expect(args, {'id': 'arena.HoverPad', 'description': 'HoverPad (lib/game/hover_pad.dart).'});
      expect(model.scriptKind('game/hover_pad.dart'), 'behaviour');

      // A name already taken never reaches the disk.
      expect(model.writeNewBehaviour('HoverPad'), isNull);
      expect(model.lastError, contains('already there'));
      expect(model.writeNewBehaviour('lower'), isNull);
      expect(model.lastError, contains('not a class name'));

      // codegen failing, or not listing the type (a compile error), is said.
      final c = model.writeNewBehaviour('Crate', inFolder: '')!;
      expect(c.rel, 'crate.dart');
      expect(await model.generateBehaviour(c, () async => 'build_runner failed'), contains('build_runner failed'));
      expect(model.lastError, startsWith('lib/crate.dart was written, but fynkel codegen failed'));
      expect(project.operations.last.$1, 'registerBehaviour');
      expect(project.operations.last.$2['id'], 'arena.HoverPad');
      expect(await model.generateBehaviour(c, () async => null), contains('did not list arena.Crate'));
    });

    test('no lib/ or no pubspec: no Scripts, no New Behaviour', () {
      final dir = Directory.systemTemp.createTempSync('fynkel_editor_noscripts');
      addTearDown(() => dir.deleteSync(recursive: true));
      final model = ProjectBrowserModel(project: FakeProject(dir: dir.path));
      addTearDown(model.dispose);
      expect(model.hasScripts, isFalse);
      expect(model.canNewBehaviour, isFalse);
      Directory('${dir.path}/lib').createSync();
      expect(model.hasScripts, isTrue);
      expect(model.canNewBehaviour, isFalse);
    });
  });

  group('ProjectPanel scripts', () {
    testWidgets('the Scripts tree, a double-click into the IDE, New ▾ → Behaviour', (tester) async {
      late Directory dir;
      await tester.runAsync(() async => dir = scriptsProject());
      addTearDown(() => dir.deleteSync(recursive: true));
      final project = FakeProject(dir: dir.path)..metadata = metadataOf([('game.Player', 'game/player.dart')]);
      final model = ProjectBrowserModel(project: project);
      addTearDown(model.dispose);
      final opened = <String>[];
      var generated = 0;
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: SizedBox(
              height: 600,
              width: 900,
              child: ProjectPanel(
                model: model,
                onOpenDocument: (_) {},
                onShowAsset: () {},
                run: RecordingRunner().call,
                onOpenScript: (file) async {
                  opened.add(file);
                  return null;
                },
                generateBehaviours: () async {
                  generated++;
                  project.metadata = metadataOf([
                    ('game.Player', 'game/player.dart'),
                    ('game.Hover', 'game/hover.dart'),
                  ]);
                  return null;
                },
              ),
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      expect(find.byKey(const Key('project.scripts.tree.root')), findsOneWidget);
      expect(find.byKey(const Key('project.scripts.tree.game')), findsOneWidget);
      await tester.tap(find.byKey(const Key('project.scripts.tree.game')));
      await tester.pumpAndSettle();
      expect(model.inScripts, isTrue);
      expect(find.byKey(const Key('project.script.game/player.dart')), findsOneWidget);
      expect(find.byKey(const Key('project.script.contents.game/player.dart')), findsOneWidget);
      expect(find.text('behaviour'), findsOneWidget);
      expect(find.byTooltip('2 of 4 scripts in lib/game'), findsOneWidget);

      // Double-click opens the file in the IDE; ↩ does too.
      final row = find.byKey(const Key('project.script.game/hud.dart'));
      await tester.tap(row);
      await tester.pump(const Duration(milliseconds: 60));
      await tester.tap(row);
      await tester.pumpAndSettle();
      expect(opened, ['${dir.path}/lib/game/hud.dart']);
      await tester.sendKeyEvent(LogicalKeyboardKey.arrowDown);
      await tester.sendKeyEvent(LogicalKeyboardKey.enter);
      await tester.pumpAndSettle();
      expect(opened.last, '${dir.path}/lib/game/player.dart');

      // New ▾ → New Behaviour…: the dialog checks the name as typed.
      await tester.tap(find.byKey(const Key('project.new')));
      await tester.pumpAndSettle();
      expect(find.text('in lib/game'), findsOneWidget);
      await tester.tap(find.byKey(const Key('project.new.behaviour')));
      await tester.pumpAndSettle();
      expect(find.byKey(const Key('project.newBehaviour')), findsOneWidget);
      await tester.enterText(find.byKey(const Key('project.newBehaviour.name')), 'hover');
      await tester.pump();
      expect(find.text('A capital letter, then letters and digits'), findsOneWidget);
      await tester.enterText(find.byKey(const Key('project.newBehaviour.name')), 'Hover');
      await tester.pump();
      expect(find.textContaining('lib/game/hover.dart opens in your IDE'), findsOneWidget);
      await tester.runAsync(() async {
        await tester.tap(find.byKey(const Key('project.newBehaviour.create')));
        await tester.pump();
      });
      await tester.pumpAndSettle();
      expect(File('${dir.path}/lib/game/hover.dart').existsSync(), isTrue);
      expect(opened.last, '${dir.path}/lib/game/hover.dart');
      expect(generated, 1);
      expect(project.operations.last.$1, 'registerBehaviour');
      expect(project.operations.last.$2['id'], 'game.Hover');
      expect(model.lastError, isNull);
      expect(find.byKey(const Key('project.script.game/hover.dart')), findsOneWidget);

      // Back to the assets.
      await tester.tap(find.byKey(const Key('project.folder.tree.root')));
      await tester.pumpAndSettle();
      expect(model.inScripts, isFalse);
      expect(find.byKey(const Key('project.scripts.list')), findsNothing);
    });

    testWidgets('without a codegen runner New ▾ has no Behaviour item', (tester) async {
      late Directory dir;
      await tester.runAsync(() async => dir = scriptsProject());
      addTearDown(() => dir.deleteSync(recursive: true));
      final model = ProjectBrowserModel(project: FakeProject(dir: dir.path));
      addTearDown(model.dispose);
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: SizedBox(
              height: 600,
              child: ProjectPanel(
                model: model,
                onOpenDocument: (_) {},
                onShowAsset: () {},
                run: RecordingRunner().call,
              ),
            ),
          ),
        ),
      );
      await tester.tap(find.byKey(const Key('project.new')));
      await tester.pumpAndSettle();
      expect(find.byKey(const Key('project.new.behaviour')), findsNothing);
    });
  });
}
